import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { ROLES } from '../utils/roles';

const Sidebar = ({ role }) => {
  const location = useLocation();

  const isActive = (path) => {
    return location.pathname === path ? 'bg-blue-700' : '';
  };

  const adminLinks = [
    { path: '/admin/dashboard', label: 'Dashboard' },
    { path: '/admin/register-doctor', label: 'Register Doctor' },
    { path: '/admin/register-receptionist', label: 'Register Receptionist' },
    { path: '/admin/doctors', label: 'List Doctors' },
    { path: '/admin/receptionists', label: 'List Receptionists' }
  ];

  const receptionistLinks = [
    { path: '/receptionist/dashboard', label: 'Dashboard' },
    { path: '/receptionist/register-patient', label: 'Register Patient' },
    { path: '/receptionist/book-appointment', label: 'Book Appointment' }
  ];

  const doctorLinks = [
    { path: '/doctor/dashboard', label: 'Dashboard' },
    { path: '/doctor/appointments', label: 'My Appointments' }
  ];

  const patientLinks = [
    { path: '/patient/dashboard', label: 'Dashboard' },
    { path: '/patient/appointments', label: 'My Appointments' },
    { path: '/patient/prescriptions', label: 'My Prescriptions' }
  ];

  const getLinks = () => {
    switch (role) {
      case ROLES.ADMIN:
        return adminLinks;
      case ROLES.RECEPTIONIST:
        return receptionistLinks;
      case ROLES.DOCTOR:
        return doctorLinks;
      case ROLES.PATIENT:
        return patientLinks;
      default:
        return [];
    }
  };

  const links = getLinks();

  return (
    <div className="bg-gray-800 text-white w-64 min-h-screen p-4">
      <h2 className="text-xl font-bold mb-6">Menu</h2>
      <ul className="space-y-2">
        {links.map((link) => (
          <li key={link.path}>
            <Link
              to={link.path}
              className={`block px-4 py-2 rounded hover:bg-blue-700 transition ${isActive(link.path)}`}
            >
              {link.label}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Sidebar;
